# verified BLS CPI release dates (the day the report hit at 8:30 ET), within data window
cpi = [
 ("2024-06-12","May'24"),("2024-07-11","Jun'24"),("2024-08-14","Jul'24"),
 ("2024-09-11","Aug'24"),("2024-10-10","Sep'24"),("2024-11-13","Oct'24"),
 ("2024-12-11","Nov'24"),("2025-01-15","Dec'24"),("2025-02-12","Jan'25"),
 ("2025-03-12","Feb'25"),("2025-04-10","Mar'25"),("2025-05-13","Apr'25"),
 ("2025-06-11","May'25"),("2025-07-15","Jun'25"),("2025-08-12","Jul'25"),
 ("2025-09-11","Aug'25"),("2025-10-24","Sep'25*"),  # *delayed by shutdown
 ("2025-12-18","Nov'25*"),  # *Oct data never published; Nov released late
 ("2026-01-13","Dec'25"),("2026-02-13","Jan'26"),("2026-03-11","Feb'26"),
 ("2026-04-10","Mar'26"),("2026-05-12","Apr'26"),
]

idx = {d: i for i, d in enumerate(time)}
rows = []
for d, lab in cpi:
    if d not in idx:
        print(f"!! {d} not a trading day in data"); continue
    i = idx[d]
    o, c, h, l, pc = opn[i], cls[i], hgh[i], low[i], cls[i - 1]
    oc = (c / o - 1) * 100          # open -> close (pure session reaction)
    dd = (c / pc - 1) * 100         # prior close -> close (gap + session)
    rng = (h - l) / pc * 100        # intraday range as % of prior close
    rows.append((d, lab, pc, o, h, l, c, oc, dd, rng))

print(f"{'date':<11}{'mo':<8}{'p.close':>8}{'open':>8}{'close':>8}{'o>c%':>7}{'pc>c%':>7}{'rng%':>7}")
for r in rows:
    print(f"{r[0]:<11}{r[1]:<8}{r[2]:>8.2f}{r[3]:>8.2f}{r[6]:>8.2f}{r[7]:>7.2f}{r[8]:>7.2f}{r[9]:>7.2f}")

oc = np.array([r[7] for r in rows]); dd = np.array([r[8] for r in rows]); rng = np.array([r[9] for r in rows])
n = len(rows)
print("\n=== SUMMARY (n =", n, "CPI days) ===")
print(f"open->close:   mean {oc.mean():+.2f}%  median {np.median(oc):+.2f}%  up {sum(oc>0)}/{n}  ({100*sum(oc>0)/n:.0f}% green)")
print(f"pclose->close: mean {dd.mean():+.2f}%  median {np.median(dd):+.2f}%  up {sum(dd>0)}/{n}  ({100*sum(dd>0)/n:.0f}% green)")
print(f"abs move (pc>c): mean {np.abs(dd).mean():.2f}%   intraday range: mean {rng.mean():.2f}%")
print(f"biggest up:  {max(rows, key=lambda r:r[8])[1]} {max(dd):+.2f}%")
print(f"biggest down:{min(rows, key=lambda r:r[8])[1]} {min(dd):+.2f}%")
# typical (non-CPI) daily for comparison
allret = np.array([(cls[i]/cls[i-1]-1)*100 for i in range(1,len(cls))])
allrng = np.array([(hgh[i]-low[i])/cls[i-1]*100 for i in range(1,len(cls))])
print(f"\nbaseline all-days: |move| mean {np.abs(allret).mean():.2f}%  range mean {allrng.mean():.2f}%  ({n} CPI vs {len(allret)} days)")

# ---------- chart: CPI-day reactions ----------
BG="#0d1117"; GREEN="#00ff41"; RED="#e53935"; GOLD="#f0b400"; TXT="#c9d1d9"; MUTE="#6e7681"; GRID="#21262d"
plt.rcParams.update({"figure.facecolor":BG,"axes.facecolor":BG,"savefig.facecolor":BG,
    "font.family":"monospace","text.color":TXT,"axes.labelcolor":TXT,"xtick.color":TXT,"ytick.color":TXT,"axes.edgecolor":GRID})
fig, ax = plt.subplots(figsize=(12,6.5))
labs=[r[1] for r in rows]; xs=np.arange(n)
cols=[GREEN if v>0 else RED for v in dd]
ax.bar(xs, dd, color=cols, edgecolor="none", zorder=3)
ax.axhline(0, color=MUTE, lw=1)
ax.axhline(dd.mean(), color=GOLD, lw=1, ls="--", label=f"mean {dd.mean():+.2f}%")
for x,v in zip(xs,dd):
    ax.text(x, v+(0.25 if v>0 else -0.25), f"{v:+.1f}", ha="center",
            va="bottom" if v>0 else "top", color=TXT, fontsize=7.5)
ax.set_xticks(xs); ax.set_xticklabels(labs, rotation=60, fontsize=8, ha="right")
ax.set_ylabel("AMZN move, prior close -> close (%)")
ax.set_title(f"AMZN on CPI release days  ·  {n} prints, Jun 2024 - May 2026  ·  {sum(dd>0)} green / {sum(dd<0)} red",
             color=TXT, fontsize=13, loc="left")
ax.grid(color=GRID, lw=0.5, axis="y"); ax.legend(facecolor="#161b22", edgecolor=GRID, labelcolor=TXT, fontsize=9)
ax.text(0.5,-0.30,"* Sep'25 delayed to Oct 24 and Nov'25 to Dec 18 by the 2025 shutdown; Oct'25 data never published.",
        transform=ax.transAxes, ha="center", color=MUTE, fontsize=8)
fig.savefig(HERE/"infographic_4.png", dpi=110, bbox_inches="tight"); plt.close(fig)
print("\nwrote infographic_4.png")
